DROP TABLE IF EXISTS `program_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `program_schedules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `program_id` bigint unsigned NOT NULL,
  `trip_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `capacity` smallint unsigned NOT NULL,
  `cost_override` decimal(12,2) DEFAULT NULL,
  `status` enum('planned','open','closed','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'planned',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_schedule` (`program_id`,`trip_date`,`start_time`),
  KEY `idx_schedules_date` (`trip_date`),
  KEY `idx_schedules_program_date` (`program_id`,`trip_date`),
  CONSTRAINT `fk_schedules_program` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_schedule_capacity` CHECK ((`capacity` > 0)),
  CONSTRAINT `chk_schedule_time` CHECK ((`end_time` > `start_time`))
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
