CREATE TABLE `programs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organizer_id` bigint unsigned NOT NULL,
  `code` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(220) COLLATE utf8mb4_unicode_ci NOT NULL,
  `education_level` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_cost_per_student` decimal(12,2) NOT NULL,
  `duration_days` tinyint unsigned NOT NULL DEFAULT '1',
  `capacity` smallint unsigned NOT NULL,
  `status` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_programs_organizer` (`organizer_id`),
  KEY `idx_program_filter` (`status`,`education_level`,`base_cost_per_student`),
  FULLTEXT KEY `ft_program_name` (`name`),
  CONSTRAINT `fk_programs_organizer` FOREIGN KEY (`organizer_id`) REFERENCES `organizers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_program_capacity` CHECK ((`capacity` > 0)),
  CONSTRAINT `chk_program_cost` CHECK ((`base_cost_per_student` >= 0))
