--
-- Table structure for table `safety_profiles`
--

DROP TABLE IF EXISTS `safety_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `safety_profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `schedule_id` bigint unsigned NOT NULL,
  `risk_level` enum('low','medium','high') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `first_aid_plan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `emergency_plan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `weather_threshold` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_contact` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `reviewed_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `schedule_id` (`schedule_id`),
  CONSTRAINT `fk_safety_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `program_schedules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

