DROP TABLE IF EXISTS `schedule_stops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule_stops` (
  `schedule_id` bigint unsigned NOT NULL,
  `place_id` bigint unsigned NOT NULL,
  `seq_no` tinyint unsigned NOT NULL,
  `activity` varchar(220) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_minutes` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`schedule_id`,`seq_no`),
  UNIQUE KEY `uq_schedule_place` (`schedule_id`,`place_id`,`seq_no`),
  KEY `fk_schedule_stops_place` (`place_id`),
  CONSTRAINT `fk_schedule_stops_place` FOREIGN KEY (`place_id`) REFERENCES `places` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_schedule_stops_schedule` FOREIGN KEY (`schedule_id`) REFERENCES `program_schedules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

